import httpx
import os

def get_trade_status(trade_id: str) -> dict:
    """
    Tra cứu trạng thái trade từ SafeExchange API.
    Args:
        trade_id: ID hoặc địa chỉ Safe của trade
    Returns:
        dict chứa thông tin trade: status, safeAddress, priceEth, buyerAddress, sellerAddress
    """
    api_url = os.getenv('SAFEEXCHANGE_API_URL', 'http://localhost:5000')
    try:
        resp = httpx.get(f'{api_url}/api/trades/{trade_id}', timeout=10)
        if resp.status_code == 200:
            t = resp.json()
            return {
                'id': t.get('id'),
                'status': t.get('status'),
                'safeAddress': t.get('safeAddress'),
                'sellerAddress': t.get('sellerAddress'),
                'buyerAddress': t.get('buyerAddress'),
                'priceEth': t.get('priceEth'),
                'onchainTradeId': t.get('onchainTradeId'),
                'snapshotNonce': t.get('snapshotNonce'),
                'deadline': str(t.get('deadline', '')),
            }
        elif resp.status_code == 404:
            return {'error': f'Không tìm thấy trade #{trade_id}'}
        else:
            return {'error': f'Lỗi API: {resp.status_code}'}
    except Exception as e:
        return {'error': str(e)}
